import { requireVendorCapability } from "../../../../lib/vendor-session";
import { submitVendorCompliance } from "../../../../lib/vendor-compliance-service";
import { vendorTrustWorkspace } from "../../../../lib/vendor-backoffice-service";
export async function POST(request:Request){try{const { principal: p }=await requireVendorCapability("compliance.submit",request,true);const b=await request.json() as Record<string,unknown>;const str=(k:string)=>typeof b[k]==="string"?String(b[k]).trim():"";await submitVendorCompliance(p,{canonicalVariantId:str("canonicalVariantId"),type:str("type"),issuer:str("issuer")||undefined,identifier:str("identifier")||undefined,mediaAssetId:str("mediaAssetId")||undefined,validTo:typeof b.validTo==="number"?b.validTo:undefined});return Response.json(await vendorTrustWorkspace(p));}catch(e){return Response.json({error:e instanceof Error?e.message:"compliance_submit_failed"},{status:400})}}
